const linhas = $input.all().map((i) => i.json);
if (linhas.length === 0) {
  return [];
}

const cab = linhas[0];
const fmtBRL = (v) => (Number(v) || 0).toLocaleString('pt-BR', { style: 'currency', currency: 'BRL' });

const PAPEIS = [
  ['chamariz', '🔥 Chamariz (puxam cliente pra loja)'],
  ['kit', '🛒 Kits (leve mais)'],
  ['perfumaria', '🧴 Perfumaria e higiene'],
  ['mip', '💊 Balcão (MIP)'],
];

const cartaz = linhas.filter((l) => l.braco === 'desconto');
const controle = linhas.filter((l) => l.braco === 'controle');

const descricaoOferta = (l) => {
  if (l.tipo_promocao === 'kit') {
    const qtd = Number(l.kit_quantidade_minima);
    const pct = Number(l.kit_percentual_desconto_item);
    const txt = pct >= 100 ? `Compre ${qtd}, pague ${qtd - 1}` : `${pct}% no ${qtd}º item`;
    return `${txt} (sai ${fmtBRL(l.preco_promocional)} cada)`;
  }
  return `${fmtBRL(l.preco_promocional)} (-${Number(l.desconto_pct)}%)`;
};

const out = [
  `📋 *Proposta de campanha — ${cab.campanha}*`,
  `Período: ${cab.inicio} a ${cab.fim}`,
  '',
  `*${cartaz.length} produtos pro cartaz:*`,
];

let n = 0;
for (const [papel, titulo] of PAPEIS) {
  const doPapel = cartaz.filter((l) => l.papel === papel);
  if (!doPapel.length) continue;
  out.push('');
  out.push(`*${titulo}*`);
  doPapel.forEach((l) => {
    n += 1;
    out.push(`${n}. ${l.produto}`);
    out.push(`   ${descricaoOferta(l)} · estoque ${l.estoque_atual}`);
  });
}

if (controle.length) {
  out.push('');
  out.push(`🔒 *${controle.length} em grupo de controle* — ficam a preço normal, sem cartaz. Servem pra medir se o cartaz fez diferença no fim do mês.`);
}

out.push('');
out.push('Remédio de uso contínuo (pressão, diabetes, colesterol, tireoide, anticoncepcional) e produto com margem abaixo de 30% ficam fora automaticamente.');
out.push('');
out.push('✅ *Próximos passos:*');
out.push('1. Abra a aba *Campanhas* no app — a proposta está no topo. Revise no lápis (ajustar preço ou excluir item) e toque em *Aprovar*.');
out.push('2. Depois de aprovada, gere os cartazes e o .txt na aba *Cartazetes* e importe o .txt no Trier.');
out.push('');
out.push('Enquanto não for aprovada, a campanha não vale pra nada: sem cartaz, sem .txt e sem alerta pros vendedores.');

return [{ json: { mensagem: out.join('\n') } }];
